// InitWithDBType initializes a new Currency record with database context and type.
// db can be *sql.DB or *sql.Tx. There is no Init without the type: the type decides the SQL
// placeholders, and a default (SQLite) silently broke code on PostgreSQL.
func (t *Currency) InitWithDBType(db database.Executor, company string, dbType database.DBType) {
	t.db = db
	t.company = company
	t.dbType = dbType
	t.oldValues = nil // Fresh record, no old values
	t.applyDefaults()
}

