// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *Currency) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *Currency) Get(primaryKey interface{}) bool {
	// A composite primary key (map[string]interface{}, values also as text)
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		key := currencyFields.KeyFromMap(pkMap)
		return t.GetByPK(key[0].(types.Code))
	}
	// The primary key itself (a table with one primary key field)
	if key, ok := currencyFields.KeyFromValue(primaryKey); ok {
		return t.GetByPK([]any{key}[0].(types.Code))
	}

	fmt.Printf("Error: Invalid primary key type for Currency.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *Currency) GetByPK(code types.Code) bool {
	// Collect arguments for query
	args := []interface{}{
		code,
	}
	return t.rec().Get(args)
}

// Insert inserts the record into the database
func (t *Currency) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Code,
		t.Last_date_modified,
		t.Last_date_adjusted,
		t.Unrealized_gains_acc,
		t.Realized_gains_acc,
		t.Unrealized_losses_acc,
		t.Realized_losses_acc,
		t.Invoice_rounding_precision,
		t.Invoice_rounding_type,
		t.Amount_rounding_precision,
		t.Unit_amount_rounding_precision,
		t.Description,
		t.Amount_decimal_places,
		t.Unit_amount_decimal_places,
		t.Appln_rounding_precision,
		t.Emu_currency,
		t.Currency_factor,
		t.Realized_gl_gains_account,
		t.Realized_gl_losses_account,
		t.Residual_gains_account,
		t.Residual_losses_account,
		t.Conv_lcy_rndg_debit_acc,
		t.Conv_lcy_rndg_credit_acc,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (code, last_date_modified, last_date_adjusted, unrealized_gains_acc, realized_gains_acc, unrealized_losses_acc, realized_losses_acc, invoice_rounding_precision, invoice_rounding_type, amount_rounding_precision, unit_amount_rounding_precision, description, amount_decimal_places, unit_amount_decimal_places, appln_rounding_precision, emu_currency, currency_factor, realized_gl_gains_account, realized_gl_losses_account, residual_gains_account, residual_losses_account, conv_lcy_rndg_debit_acc, conv_lcy_rndg_credit_acc) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (code) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Currency: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(CurrencyTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *Currency) InsertAll(records []*Currency, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Code,
			r.Last_date_modified,
			r.Last_date_adjusted,
			r.Unrealized_gains_acc,
			r.Realized_gains_acc,
			r.Unrealized_losses_acc,
			r.Realized_losses_acc,
			r.Invoice_rounding_precision,
			r.Invoice_rounding_type,
			r.Amount_rounding_precision,
			r.Unit_amount_rounding_precision,
			r.Description,
			r.Amount_decimal_places,
			r.Unit_amount_decimal_places,
			r.Appln_rounding_precision,
			r.Emu_currency,
			r.Currency_factor,
			r.Realized_gl_gains_account,
			r.Realized_gl_losses_account,
			r.Residual_gains_account,
			r.Residual_losses_account,
			r.Conv_lcy_rndg_debit_acc,
			r.Conv_lcy_rndg_credit_acc,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyTableName)
	columns := []string{"code", "last_date_modified", "last_date_adjusted", "unrealized_gains_acc", "realized_gains_acc", "unrealized_losses_acc", "realized_losses_acc", "invoice_rounding_precision", "invoice_rounding_type", "amount_rounding_precision", "unit_amount_rounding_precision", "description", "amount_decimal_places", "unit_amount_decimal_places", "appln_rounding_precision", "emu_currency", "currency_factor", "realized_gl_gains_account", "realized_gl_losses_account", "residual_gains_account", "residual_losses_account", "conv_lcy_rndg_debit_acc", "conv_lcy_rndg_credit_acc"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *Currency) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			setClauses = append(setClauses, "code = ?")
			values = append(values, t.Code)
		}
		if t.hasFieldChanged("last_date_modified") {
			setClauses = append(setClauses, "last_date_modified = ?")
			values = append(values, t.Last_date_modified)
		}
		if t.hasFieldChanged("last_date_adjusted") {
			setClauses = append(setClauses, "last_date_adjusted = ?")
			values = append(values, t.Last_date_adjusted)
		}
		if t.hasFieldChanged("unrealized_gains_acc") {
			setClauses = append(setClauses, "unrealized_gains_acc = ?")
			values = append(values, t.Unrealized_gains_acc)
		}
		if t.hasFieldChanged("realized_gains_acc") {
			setClauses = append(setClauses, "realized_gains_acc = ?")
			values = append(values, t.Realized_gains_acc)
		}
		if t.hasFieldChanged("unrealized_losses_acc") {
			setClauses = append(setClauses, "unrealized_losses_acc = ?")
			values = append(values, t.Unrealized_losses_acc)
		}
		if t.hasFieldChanged("realized_losses_acc") {
			setClauses = append(setClauses, "realized_losses_acc = ?")
			values = append(values, t.Realized_losses_acc)
		}
		if t.hasFieldChanged("invoice_rounding_precision") {
			setClauses = append(setClauses, "invoice_rounding_precision = ?")
			values = append(values, t.Invoice_rounding_precision)
		}
		if t.hasFieldChanged("invoice_rounding_type") {
			setClauses = append(setClauses, "invoice_rounding_type = ?")
			values = append(values, t.Invoice_rounding_type)
		}
		if t.hasFieldChanged("amount_rounding_precision") {
			setClauses = append(setClauses, "amount_rounding_precision = ?")
			values = append(values, t.Amount_rounding_precision)
		}
		if t.hasFieldChanged("unit_amount_rounding_precision") {
			setClauses = append(setClauses, "unit_amount_rounding_precision = ?")
			values = append(values, t.Unit_amount_rounding_precision)
		}
		if t.hasFieldChanged("description") {
			setClauses = append(setClauses, "description = ?")
			values = append(values, t.Description)
		}
		if t.hasFieldChanged("amount_decimal_places") {
			setClauses = append(setClauses, "amount_decimal_places = ?")
			values = append(values, t.Amount_decimal_places)
		}
		if t.hasFieldChanged("unit_amount_decimal_places") {
			setClauses = append(setClauses, "unit_amount_decimal_places = ?")
			values = append(values, t.Unit_amount_decimal_places)
		}
		if t.hasFieldChanged("appln_rounding_precision") {
			setClauses = append(setClauses, "appln_rounding_precision = ?")
			values = append(values, t.Appln_rounding_precision)
		}
		if t.hasFieldChanged("emu_currency") {
			setClauses = append(setClauses, "emu_currency = ?")
			values = append(values, t.Emu_currency)
		}
		if t.hasFieldChanged("currency_factor") {
			setClauses = append(setClauses, "currency_factor = ?")
			values = append(values, t.Currency_factor)
		}
		if t.hasFieldChanged("realized_gl_gains_account") {
			setClauses = append(setClauses, "realized_gl_gains_account = ?")
			values = append(values, t.Realized_gl_gains_account)
		}
		if t.hasFieldChanged("realized_gl_losses_account") {
			setClauses = append(setClauses, "realized_gl_losses_account = ?")
			values = append(values, t.Realized_gl_losses_account)
		}
		if t.hasFieldChanged("residual_gains_account") {
			setClauses = append(setClauses, "residual_gains_account = ?")
			values = append(values, t.Residual_gains_account)
		}
		if t.hasFieldChanged("residual_losses_account") {
			setClauses = append(setClauses, "residual_losses_account = ?")
			values = append(values, t.Residual_losses_account)
		}
		if t.hasFieldChanged("conv_lcy_rndg_debit_acc") {
			setClauses = append(setClauses, "conv_lcy_rndg_debit_acc = ?")
			values = append(values, t.Conv_lcy_rndg_debit_acc)
		}
		if t.hasFieldChanged("conv_lcy_rndg_credit_acc") {
			setClauses = append(setClauses, "conv_lcy_rndg_credit_acc = ?")
			values = append(values, t.Conv_lcy_rndg_credit_acc)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "last_date_modified = ?")
		values = append(values, t.Last_date_modified)
		setClauses = append(setClauses, "last_date_adjusted = ?")
		values = append(values, t.Last_date_adjusted)
		setClauses = append(setClauses, "unrealized_gains_acc = ?")
		values = append(values, t.Unrealized_gains_acc)
		setClauses = append(setClauses, "realized_gains_acc = ?")
		values = append(values, t.Realized_gains_acc)
		setClauses = append(setClauses, "unrealized_losses_acc = ?")
		values = append(values, t.Unrealized_losses_acc)
		setClauses = append(setClauses, "realized_losses_acc = ?")
		values = append(values, t.Realized_losses_acc)
		setClauses = append(setClauses, "invoice_rounding_precision = ?")
		values = append(values, t.Invoice_rounding_precision)
		setClauses = append(setClauses, "invoice_rounding_type = ?")
		values = append(values, t.Invoice_rounding_type)
		setClauses = append(setClauses, "amount_rounding_precision = ?")
		values = append(values, t.Amount_rounding_precision)
		setClauses = append(setClauses, "unit_amount_rounding_precision = ?")
		values = append(values, t.Unit_amount_rounding_precision)
		setClauses = append(setClauses, "description = ?")
		values = append(values, t.Description)
		setClauses = append(setClauses, "amount_decimal_places = ?")
		values = append(values, t.Amount_decimal_places)
		setClauses = append(setClauses, "unit_amount_decimal_places = ?")
		values = append(values, t.Unit_amount_decimal_places)
		setClauses = append(setClauses, "appln_rounding_precision = ?")
		values = append(values, t.Appln_rounding_precision)
		setClauses = append(setClauses, "emu_currency = ?")
		values = append(values, t.Emu_currency)
		setClauses = append(setClauses, "currency_factor = ?")
		values = append(values, t.Currency_factor)
		setClauses = append(setClauses, "realized_gl_gains_account = ?")
		values = append(values, t.Realized_gl_gains_account)
		setClauses = append(setClauses, "realized_gl_losses_account = ?")
		values = append(values, t.Realized_gl_losses_account)
		setClauses = append(setClauses, "residual_gains_account = ?")
		values = append(values, t.Residual_gains_account)
		setClauses = append(setClauses, "residual_losses_account = ?")
		values = append(values, t.Residual_losses_account)
		setClauses = append(setClauses, "conv_lcy_rndg_debit_acc = ?")
		values = append(values, t.Conv_lcy_rndg_debit_acc)
		setClauses = append(setClauses, "conv_lcy_rndg_credit_acc = ?")
		values = append(values, t.Conv_lcy_rndg_credit_acc)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Code)
	}
	// Renamed key fields that other tables refer to (Rename): carried over below
	type renamedKey struct {
		field    string
		old, new interface{}
	}
	var renamed []renamedKey
	if t.oldValues != nil {
		if t.hasFieldChanged("code") {
			renamed = append(renamed, renamedKey{"code", t.oldValues["code"], t.Code})
		}
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND code = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Currency: %v\n", err)
		return false
	}
	// A temporary record's rename stays in the record: other tables are not changed
	for _, r := range renamed {
		if t.temp != nil {
			break
		}
		if err := t.renameReferences(r.field, r.old, r.new); err != nil {
			fmt.Printf("Error: Failed to rename references to Currency: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *Currency) hasFieldChanged(fieldName string) bool {
	return currencyFields.Changed(t.fieldRef, t.oldValues, fieldName)
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *Currency) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *Currency) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"code": {{"Bank_Account", false, "currency_code", "", 0}, {"Bank_Account_Ledger_Entry", false, "currency_code", "", 0}, {"Business_Unit", false, "currency_code", "", 0}, {"Currency_Exchange_Rate", false, "currency_code", "", 0}, {"Currency_Exchange_Rate", false, "relational_currency_code", "", 0}, {"Currency_for_Fin_Charge_Terms", false, "currency_code", "", 0}, {"Currency_for_Reminder_Level", false, "currency_code", "", 0}, {"Cust_Invoice_Disc", false, "currency_code", "", 0}, {"Customer Ledger Entry", false, "currency_code", "", 0}, {"Customer Ledger Entry", false, "closed_by_currency_code", "", 0}, {"Customer", false, "currency_code", "", 0}, {"Customer_Bank_Account", false, "currency_code", "", 0}, {"Exch_Rate_Adjmt_Reg", false, "currency_code", "", 0}, {"Finance_Charge_Memo_Header", false, "currency_code", "", 0}, {"Gen_Journal_Line", false, "currency_code", "", 0}, {"Gen_Journal_Line", false, "source_currency_code", "", 0}, {"General_Ledger_Setup", false, "additional_reporting_currency", "", 0}, {"Issued_Fin_Charge_Memo_Header", false, "currency_code", "", 0}, {"Issued_Reminder_Header", false, "currency_code", "", 0}, {"Item_Journal_Line", false, "source_currency_code", "", 0}, {"Item_Price", false, "currency_code", "", 0}, {"Item_Price_Change", false, "currency_code", "", 0}, {"Item_Vendor", false, "currency_code", "", 0}, {"Project_Journal_Line", false, "source_currency_code", "", 0}, {"Purch_Cr_Memo_Hdr", false, "currency_code", "", 0}, {"Purch_Cr_Memo_Line", false, "currency_code", "", 0}, {"Purch_Inv_Header", false, "currency_code", "", 0}, {"Purch_Inv_Line", false, "currency_code", "", 0}, {"Purch_Rcpt_Header", false, "currency_code", "", 0}, {"Purch_Rcpt_Line", false, "currency_code", "", 0}, {"Purchase_Header", false, "currency_code", "", 0}, {"Purchase_Line", false, "currency_code", "", 0}, {"Reminder_Header", false, "currency_code", "", 0}, {"Requisition_Line", false, "currency_code", "", 0}, {"Resource_Price", false, "currency_code", "", 0}, {"Resource_Price_Change", false, "currency_code", "", 0}, {"Sales_Cr_Memo_Header", false, "currency_code", "", 0}, {"Sales_Cr_Memo_Line", false, "currency_code", "", 0}, {"Sales_Header", false, "currency_code", "", 0}, {"Sales_Invoice_Header", false, "currency_code", "", 0}, {"Sales_Invoice_Line", false, "currency_code", "", 0}, {"Sales_Line", false, "currency_code", "", 0}, {"Sales_Shipment_Header", false, "currency_code", "", 0}, {"Sales_Shipment_Line", false, "currency_code", "", 0}, {"Vendor", false, "currency_code", "", 0}, {"Vendor_Bank_Account", false, "currency_code", "", 0}, {"Vendor_Invoice_Disc", false, "currency_code", "", 0}, {"Vendor Ledger Entry", false, "currency_code", "", 0}, {"Vendor Ledger Entry", false, "closed_by_currency_code", "", 0}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

