// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *Currency) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "invoice_rounding_precision":
			column = "invoice_rounding_precision"
		case "amount_rounding_precision":
			column = "amount_rounding_precision"
		case "unit_amount_rounding_precision":
			column = "unit_amount_rounding_precision"
		case "appln_rounding_precision":
			column = "appln_rounding_precision"
		case "currency_factor":
			column = "currency_factor"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Currency", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Currency.%s: %w", column, err)
		}
		switch column {
		case "invoice_rounding_precision":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Currency.%s: %w", column, err)
			}
			t.Invoice_rounding_precision = d
		case "amount_rounding_precision":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Currency.%s: %w", column, err)
			}
			t.Amount_rounding_precision = d
		case "unit_amount_rounding_precision":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Currency.%s: %w", column, err)
			}
			t.Unit_amount_rounding_precision = d
		case "appln_rounding_precision":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Currency.%s: %w", column, err)
			}
			t.Appln_rounding_precision = d
		case "currency_factor":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Currency.%s: %w", column, err)
			}
			t.Currency_factor = d
		}
	}
	return nil
}

// LockTable locks the table until the transaction ends (classic LOCKTABLE): on Postgres a
// table lock (tables.LockTable) and the following reads (Get, FindFirst, FindLast, FindSet)
// lock the rows they read (SELECT … FOR UPDATE); SQLite locks the whole database on write
// anyway. Use it inside a transaction.
func (t *Currency) LockTable() {
	if !t.lockForUpdate {
		tables.LockTable(t.db, t.dbType, t.company, CurrencyTableName)
	}
	t.lockForUpdate = true
}

